DO $guard$ BEGIN
IF (SELECT count(*) FROM pg_policy WHERE polrelid='public.drv_missions'::regclass)<>1 OR NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.drv_missions'::regclass AND polname='missions read' AND polcmd='r' AND polpermissive AND polroles=ARRAY['authenticated'::regrole::oid] AND md5(pg_get_expr(polqual,polrelid))='73dcff744eb3ec0259e79d48f0dde1ea') THEN RAISE EXCEPTION '0245: policy drift'; END IF;
IF (SELECT relacl::text FROM pg_class WHERE oid='public.drv_missions'::regclass) IS DISTINCT FROM '{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,sandbox_exec=ar/postgres}' THEN RAISE EXCEPTION '0245: grants drift'; END IF;
IF md5(pg_get_functiondef('cpn_my_entrepreneur()'::regprocedure))<>'5107c5489df70245869fc0206b2516e0' OR (SELECT proacl::text FROM pg_proc WHERE oid='cpn_my_entrepreneur()'::regprocedure)<>'{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: entrepreneur helper drift'; END IF;
IF md5(pg_get_functiondef('driver_mission_access(uuid,boolean)'::regprocedure))<>'e91b36f5f74c6851e440575280af5afa' OR (SELECT proacl::text FROM pg_proc WHERE oid='driver_mission_access(uuid,boolean)'::regprocedure)<>'{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: driver helper drift'; END IF;
IF md5(pg_get_functiondef('fleet_member_role(uuid)'::regprocedure))<>'41c347ea041497c6e3c0a0642dc65ad4' OR (SELECT proacl::text FROM pg_proc WHERE oid='fleet_member_role(uuid)'::regprocedure)<>'{=X/postgres,postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: membership helper drift'; END IF;
IF md5(pg_get_functiondef('has_role(uuid,app_role)'::regprocedure))<>'6e055322eaad390f6c2c3ef45fec6857' OR (SELECT proacl::text FROM pg_proc WHERE oid='has_role(uuid,app_role)'::regprocedure)<>'{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: role helper drift'; END IF;
END $guard$;
ALTER POLICY "missions read" ON public.drv_missions USING (has_role(auth.uid(), 'admin'::app_role) OR (requisition_id IS NOT NULL AND user_id = auth.uid() AND driver_mission_access(id)) OR (entrepreneur_id = cpn_my_entrepreneur() AND NOT EXISTS (SELECT 1 FROM public.jsc_company_members m WHERE m.user_id = auth.uid() AND m.role = 'chauffeur') AND (company_id IS NULL OR public.fleet_member_role(company_id) IN ('proprietaire','gestionnaire'))));